      backup_text =
        "type Operation = (name=String, requires=[(enforced=Bool, String)], \
         ensures=[(enforced=Bool, String)],  operation=?, notes=[String]) in\n\n\
         # Polymorphic type limitation: Note for these operations the \
         constraint isn't true for the function over generic tables but is \
         true when applied to concrete types #\n\n\
         [\n\
         (name=\"emptyTable\",\n\
         requires=[],\n\
         ensures=[\n\
         (enforced=^^check(true), \"schema(t) is equal to []\"),\n\
         (enforced=^^check(false), \"nrows(t) is equal to 0\")\n\
         ],\n\
         operation= [] : [()],\n\
         notes=[]\n\
         ),\n\
         (\n\
         name=\"addRows\",\n\
         requires=[(enforced=^^check(true), \"for all r in rs, schema(r) is \
         equal to schema(t1)\")],\n\
         ensures=[\n\
         (enforced=^^check(true), \"schema(t2) is equal to schema(t1)\"),\n\
         (enforced=^^check(false), \"nrows(t2) is equal to nrows(t1) + \
         length(rs)\")\n\
         ],\n\
         operation=let addRows = typfun row ->  fun (r : row, rs : [row]) -> \
         rs @ [r]  in addRows,\n\
         notes=[]\n\
         ),\n\
         (\n\
         name=\"addColumn\",\n\
         requires=[\n\
         (enforced=^^check(false), \"c is not in header(t1)\"),\n\
         (enforced=^^check(false), \"length(vs) is equal to nrows(t1)\")\n\
         ],\n\
         ensures=[\n\
         (enforced=^^check(false), \"header(t2) is equal to concat(header(t1), \
         [c])\"), \n\
         (enforced=^^check(false), \"for all c' in header(t1), schema(t2)[c'] \
         is equal to schema(t1)[c']\"), \n\
         (enforced=^^check(false), \"schema(t2)[c] is the sort of elements of \
         vs\"), \n\
         (enforced=^^check(false), \"nrows(t2) is equal to nrows(t1)\")\n\
         ],\n\
         operation= fun (t : [?], c : String, vs: [?]) ->\n\
         zip(t, vs)\n\
         |> map(_, fun (r, v) -> from_lvs(to_lvs(r) @ [(c, v)])),\n\
         notes=[\n\
         ^^text(\"Polymorphic type limitation stops most ensured constraints\"),\n\
         ^^text(\"Lack of first class labels requires writing this with \
         from_lvs.\\nIf doing this with concrete data you can do the following \
         (which if we had implicit polymophism would give full typing):\");\n\
         let t = [(a=1,b=\"hello\"),(a=2,b=\"world\"),(a=3,b=\"!\")] in let vs \
         = [1,2,3] in zip(t,vs) |> map(_, fun (t,v) -> t ... (c=v))\n\
         ;\n\
         ]\n\
         ),\n\
         (\n\
         name=\"buildColumn\", \n\
         requires=[(enforced=^^check(false), \"c is not in header(t1)\")],\n\
         ensures=[\n\
         (enforced=^^check(false), \"schema(r) is equal to schema(t1)\"),\n\
         (enforced=^^check(false), \"header(t2) is equal to concat(header(t1), \
         [c])\"),\n\
         (enforced=^^check(false), \"for all c' in header(t1), schema(t2)[c'] \
         is equal to schema(t1)[c']\"),\n\
         (enforced=^^check(false), \"schema(t2)[c] is equal to the sort of v\"),\n\
         (enforced=^^check(false), \"nrows(t2) is equal to nrows(t1)\")\n\
         ],\n\
         operation=fun (t :[?], c :String, f : ? -> ?) ->\n\
         map(t,fun (r) ->from_lvs(to_lvs(r) @[(c,f(r))])),\n\
         notes=[\n\
         \"Polymorphic type limitation stops most ensured constraints\",\n\
         ^^text(\"Lack of first class labels requires writing this with \
         from_lvs.\\nIf doing this with concrete data you can do the \
         following:\");\n\
         let t = [(a=1,b=\"hello\"),(a=2,b=\"world\"),(a=3,b=\"!\")] in map(t, \
         fun (t) -> t ... (c=t.a + 2))\n\
         ; \n\
         ]\n\
         ),\n\
         (\n\
         name=\"vcat\",\n\
         requires=[(enforced=^^check(true), \"schema(t1) is equal to \
         schema(t2)\")],\n\
         ensures=[(enforced=^^check(true), \"schema(t3) is equal to \
         schema(t1)\"), (enforced=^^check(false), \"nrows(t3) is equal to \
         nrows(t1) + nrows(t2)\")],\n\
         operation= typfun r -> fun (t1:[r],t2:[r]) -> t1 @ t2,\n\
         notes=[]\n\
         ),\n\
         (\n\
         name=\"hcat\",\n\
         requires=[\n\
         (enforced=^^check(false), \"concat(header(t1), header(t2)) has no \
         duplicates\"),\n\
         (enforced=^^check(false), \"nrows(t1) is equal to nrows(t2)\")\n\
         ],\n\
         ensures=[\n\
         (enforced=^^check(false), \"schema(t3) is equal to concat(schema(t1), \
         schema(t2))\"),\n\
         (enforced=^^check(false), \"nrows(t3) is equal to nrows(t1)\")\n\
         ],\n\
         operation=fun (t1:[?], t2:[?]) ->\n\
         zip(t1, t2)\n\
         |> map(_, fun (r1, r2) -> r1 ... r2),\n\
         notes=[\n\
         \"Polymorphic type limitation prevents enforcing structural \
         guarantees unless table row types are known.\",\n\
         \"Example (assuming concrete structure):\",\n\
         let t1 = [(name=\"Bob\", age=12), (name=\"Alice\", age=17)] in\n\
         let t2 = [(color=\"blue\", quiz1=8), (color=\"green\", quiz1=6)] in\n\
         zip(t1, t2) |> map(_, fun (r1, r2) -> r1 ... r2);\n\
         ]\n\
         ),\n\
         (\n\
         name=\"values\",\n\
         requires=[\n\
         (enforced=^^check(false), \"length(rs) is positive\"),\n\
         (enforced=^^check(true), \"for all r in rs, schema(r) is equal to \
         schema(rs[0])\")\n\
         ],\n\
         ensures=[\n\
         (enforced=^^check(true), \"schema(t) is equal to schema(rs[0])\"),\n\
         (enforced=^^check(true), \"nrows(t) is equal to length(rs)\")\n\
         ],\n\
         operation=typfun row -> fun (rs: [row]) -> rs,\n\
         notes=[\n\
         ^^text(\"Hazel's tables are lists so this is just the identity \
         function\")\n\
         ]\n\
         ),\n\
         (\n\
         name=\"crossJoin\",\n\
         requires=[\n\
         (enforced=false, \"concat(header(t1), header(t2)) has no duplicates\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"schema(t3) is equal to concat(schema(t1), \
         schema(t2))\"),\n\
         (enforced=false, \"nrows(t3) is equal to nrows(t1) * nrows(t2)\")\n\
         ],\n\
         operation=fun (t1 : [?], t2 : [?]) ->\n\
         flat_map(t1, fun r1 -> map(t2, fun r2 -> r1 ... r2)),\n\
         notes=[\n\
         \"Tuple extension (`...`) combines each pair of rows, left then \
         right; overlapping labels will be overwritten by right-hand side.\",\n\
         \"Polymorphic type limitation applies\226\128\148type constraints are \
         best enforced when row types are known concretely.\",\n\
         \"Hazel does not statically check for duplicate labels in tuple \
         extension but applies a update for clashing labels.\", \n\
         \"Example with concrete data:\",\n\
         let t1 = [(name=\"Alice\"), (name=\"Bob\")] in\n\
         let t2 = [(quiz=1), (quiz=2)] in\n\
         flat_map(t1, fun r1 -> map(t2, fun r2 -> r1 ... r2))\n\
         ; \n\
         ]\n\
         ),\n\
         (\n\
         name=\"leftJoin\",\n\
         requires=[\n\
         (enforced=false, \"cs has no duplicates\"),\n\
         (enforced=false, \"for all c in cs, c is in header(t1)\"),\n\
         (enforced=false, \"for all c in cs, c is in header(t2)\"),\n\
         (enforced=false, \"for all c in cs, schema(t1)[c] is equal to \
         schema(t2)[c]\"),\n\
         (enforced=false, \"concat(header(t1), removeAll(header(t2), cs)) has \
         no duplicates\")\n\
         ],\n\
         ensures=[\n\
         (enforced=false, \"header(t3) is equal to concat(header(t1), \
         removeAll(header(t2), cs))\"),\n\
         (enforced=false, \"for all c in header(t1), schema(t3)[c] is equal to \
         schema(t1)[c]\"),\n\
         (enforced=false, \"for all c in removeAll(header(t2), cs), \
         schema(t3)[c] is equal to schema(t2)[c]\"),\n\
         (enforced=false, \"nrows(t3) is equal to nrows(t1) if \
         distinct(selectColumns(t2, cs)) is equal to selectColumns(t2, cs), \
         otherwise each row of t1 may have several matches\")\n\
         ],\n\
         operation=let project_labels_str = fun (v,cs) ->to_lvs(v) |> \
         filter(_, fun e ->mem(cs,e.label)) |> from_lvs in\n\
         let omit_labels_str = fun (v,cs) ->to_lvs(v) |> filter(_, fun e -> \
         !mem(cs,e.label)) |> from_lvs in\n\
         let make_optional = fun (v) ->to_lvs(v) |> map(_, fun e ->e \
         ...(value=Some(e.value))) |> from_lvs in               \n\
         let left_join = fun (t1:[?], t2:[?], cs:[String]) ->\n\
         let right_columns =case hd_opt(t2) \n\
         |None =>[]\n\
         |Some(v) =>to_lvs(v) |>map(_,fun e ->e.label) \n\
         end in  \n\
         flat_map(t1,fun r1 ->\n\
         let matched = filter(t2,fun r2 ->project_labels_str(r2,cs) == \
         project_labels_str(r1,cs)) in\n\
         case matched\n\
         | [] =>[r1 ...(from_lvs(map(filter(right_columns,fun e -> !mem(cs, \
         e)),fun lc ->(label=lc,value=None))))]\n\
         | _ =>map(matched,fun r2 ->r1 \
         ...(make_optional(omit_labels_str(r2,cs)))) \n\
         end\n\
         ) \n\
         in\n\
         ,\n\
         notes=[\n\
         \"Since we don't have the schema as a runtime value there's no way to \
         dynamically build up the right table columns unless there's at least \
         one row. So we extract the columns from the first row.\",\n\
         \"If there is no row we just return the lefthand table's columns\"\n\
         ]\n\
         )\n\
         ]\n\n\
         : \n\
         [Operation]\n\n";
    } )
